class Solution:
    def bestUniqueBundle(self, prices: List[int], k: int) -> int:
        best = 0
        for i in range(len(prices) - k + 1):
            window = prices[i:i + k]
            if len(set(window)) == k:
                best = max(best, sum(window))
        return best

