class Solution {
    public long bestUniqueBundle(int[] prices, int k) {
        long best = 0;
        for (int i = 0; i + k <= prices.length; i++) {
            Set<Integer> seen = new HashSet<>();
            long total = 0;
            for (int j = i; j < i + k; j++) { seen.add(prices[j]); total += prices[j]; }
            if (seen.size() == k) best = Math.max(best, total);
        }
        return best;
    }
}

