long long bestUniqueBundle(int* prices, int pricesSize, int k) {
    int* mark = calloc(100001, sizeof(int));
    long long best = 0;
    for (int i = 0; i + k <= pricesSize; i++) {
        long long total = 0;
        int ok = 1;
        for (int j = i; j < i + k && ok; j++) {
            if (mark[prices[j]] == i + 1) ok = 0;
            mark[prices[j]] = i + 1;
            total += prices[j];
        }
        if (ok && total > best) best = total;
    }
    free(mark);
    return best;
}

