class Solution:
    def bestUniqueBundle(self, prices: List[int], k: int) -> int:
        count = [0] * 100001
        dup = total = best = 0
        for i, v in enumerate(prices):
            count[v] += 1
            if count[v] == 2:
                dup += 1
            total += v
            if i >= k:
                u = prices[i - k]
                count[u] -= 1
                if count[u] == 1:
                    dup -= 1
                total -= u
            if i >= k - 1 and dup == 0:
                best = max(best, total)
        return best

