class Solution {
    public long bestUniqueBundle(int[] prices, int k) {
        int[] count = new int[100001];
        int dup = 0;
        long total = 0, best = 0;
        for (int i = 0; i < prices.length; i++) {
            if (++count[prices[i]] == 2) dup++;
            total += prices[i];
            if (i >= k) {
                if (--count[prices[i - k]] == 1) dup--;
                total -= prices[i - k];
            }
            if (i >= k - 1 && dup == 0) best = Math.max(best, total);
        }
        return best;
    }
}

